"""Shared reading preferences; local to each browser, never changes transaction data."""
CSS='''<style id=reading-styles>
[hidden]{display:none!important}
@media screen{
details>summary{position:relative;display:block;list-style:none;box-sizing:border-box;min-height:64px;padding:14px 18px 14px 54px!important;margin:10px 0;border:1px solid #a68c59;border-radius:12px;background:#243b2e;color:#fff1d5;font-size:17px;font-weight:700;line-height:1.6;cursor:pointer;box-shadow:0 2px 0 #050c0880;overflow-wrap:anywhere}
details>summary::-webkit-details-marker{display:none}
details>summary::marker{content:''}
details>summary::before{content:'+';position:absolute;left:15px;top:16px;display:grid;place-items:center;width:26px;height:26px;border-radius:7px;background:#efcc8c;color:#17251c;font-size:23px;font-weight:700;line-height:1}
details>summary::after{content:'กดเพื่อเปิดดู';display:block;margin-top:4px;font-size:14px;font-weight:400;color:#e8d6b3}
details[open]>summary{background:#304a39;border-color:#efcc8c}
details[open]>summary::before{content:'−'}
details[open]>summary::after{content:'เปิดอยู่ · กดเพื่อย่อเก็บ'}
details>summary:hover{background:#36513e;border-color:#f4d9a1}
details>summary:focus-visible{outline:3px solid #ffdd9b;outline-offset:4px}
html[data-reading-size=large] details>summary{font-size:22px;line-height:1.65}
html[data-reading-size=large] details>summary::after{font-size:18px}
html[data-reading-contrast=high] details>summary{background:#193a26;color:#fff;border:2px solid #ffdb8d}
html[data-reading-contrast=high] details>summary::after{color:#fff}
.reading-tools{display:flex;align-items:center;justify-content:flex-end;flex-wrap:wrap;gap:8px;margin:14px 0;padding:12px;border:1px solid #70867a;border-radius:12px;background:#17281f;color:#f3f7f4;font-size:16px;line-height:1.6}.reading-tools button{min-height:44px;padding:10px 14px;color:#fff;background:#334d40;border:1px solid #8da495}.reading-tools button[aria-pressed=true]{color:#132218;background:#f0ce8c;border-color:#f0ce8c}.reading-tools small{color:#e0eae2;font-size:14px}
body{line-height:1.65}.muted,small,th{color:#c4d1c9}label{color:#d5e0d9}button,.button,input:not([type=hidden]):not([type=checkbox]):not([type=radio]),select,textarea{min-height:44px}button,.button{font-size:16px}.customer-nav a,.chip{min-height:44px;display:inline-flex;align-items:center}.customer-nav a{font-size:15px}input[type=checkbox],input[type=radio]{min-width:22px;min-height:22px;accent-color:#efcc8c}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #f5d596;outline-offset:4px}.reading-tools button:focus-visible{outline-color:white}
html[data-reading-size=large] body{font-size:20px!important}html[data-reading-size=large] :is(p,label,td,th,small,.muted,.badge,.chip,.customer-nav a,.menu-description,.menu-note,.table-meta,.step,.receipt-meta,.quantity input,.menu-bottom button,button,.button,input,select,textarea){font-size:20px!important;line-height:1.65!important}html[data-reading-size=large] .menu-info h3{font-size:23px!important;line-height:1.5}html[data-reading-size=large] h2{font-size:28px}html[data-reading-size=large] h1{font-size:34px}html[data-reading-size=large] .reading-tools small{font-size:16px!important}html[data-reading-size=large] .quantity{flex-shrink:0}html[data-reading-size=large] .quantity input{width:55px!important}html[data-reading-size=large] .quantity button{width:46px}html[data-reading-size=large] .bottom-bar{flex-wrap:wrap;gap:8px}html[data-reading-size=large] .customer{padding-bottom:190px}html[data-reading-size=large] .bottom-bar small{font-size:17px!important}html[data-reading-size=large] .receipt-sheet{font-size:23px!important}
html[data-reading-contrast=high]{--bg:#080f0b;--panel:#0c1a12;--border:#9fb5a7;--muted:#eef6f0;--gold:#ffdb8d}html[data-reading-contrast=high] body{color:#fff!important;background:#080f0b!important}html[data-reading-contrast=high] :is(.panel,.card,.tablecard,.menu-item,.subtle,.success-card,.work-priority,.quick-order,.reading-tools,.bottom-bar,.filters,aside){background:#0d1d14!important;border-color:#9fb5a7!important}html[data-reading-contrast=high] :is(small,.muted,label,th,.menu-description,.menu-note,.customer footer,.hero p,.table-meta,.step){color:#f1f7f3!important}html[data-reading-contrast=high] :is(input,select,textarea){color:#fff;background:#080f0b;border-color:#b0c9b9}html[data-reading-contrast=high] :is(button,.button,.chip.selected){background:#ffdb8d;color:#112016}html[data-reading-contrast=high] :is(.secondary,button[aria-pressed=false]){background:#294e37;color:#fff;border:1px solid #adcab7}html[data-reading-contrast=high] .badge{background:#284f36;color:white}html[data-reading-contrast=high] .receipt-sheet,html[data-reading-contrast=high] .receipt-sheet :is(p,small,.receipt-meta){background:white!important;color:black!important}
.next-step-box{border-left:4px solid #efce8d;background:#102319;padding:16px 20px;margin:18px 0;line-height:1.8}.confirmation-lines{margin:15px 0;padding-left:25px}.confirmation-lines li{margin:8px 0}.confirmation-total{font-size:22px;font-weight:700}.confirmation-progress{display:flex;flex-wrap:wrap;gap:8px;padding:0;list-style:none}.confirmation-progress li{padding:8px 12px;border:1px solid #8da495;border-radius:8px}.confirmation-progress .current{background:#edcc8e;color:#122519;font-weight:700}.confirmation-progress .done{background:#244b32;color:#effbf1}.confirmation-code{overflow-wrap:anywhere}
@media(max-width:600px){.reading-tools{justify-content:flex-start;padding:10px}.reading-tools button{flex:1;white-space:normal}.reading-tools small{flex-basis:100%}html[data-reading-size=large] .menu-grid{grid-template-columns:1fr!important}html[data-reading-size=large] .menu-item{grid-template-columns:78px minmax(0,1fr)}html[data-reading-size=large] .menu-art{width:auto!important}html[data-reading-size=large] .menu-bottom{flex-direction:column;align-items:stretch}.reading-tools,main,.customer{min-width:0}.reading-tools button{max-width:100%}.next-actions .button{white-space:normal}}
}
@media print{.reading-tools{display:none!important}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;animation:none!important;transition:none!important}}
</style>'''
SCRIPT='''<div class="reading-tools" id=reading-tools role=group aria-label="ตั้งค่าการอ่าน"><span>การอ่าน</span><button type=button id=reading-size aria-pressed=false>ตัวอักษรใหญ่</button><button type=button id=reading-contrast aria-pressed=false>สีชัดขึ้น</button><small>จำการตั้งค่าในเบราว์เซอร์นี้</small></div><script>(()=>{const root=document.documentElement,tools=document.querySelector('#reading-tools'),size=document.querySelector('#reading-size'),contrast=document.querySelector('#reading-contrast');function apply(key,value){root.setAttribute('data-reading-'+key,value);const button=key==='size'?size:contrast,on=value===(key==='size'?'large':'high');button.setAttribute('aria-pressed',String(on));try{localStorage.setItem('jupiter-reading-'+key,value)}catch{}}for(const key of ['size','contrast']){let value='normal';try{value=localStorage.getItem('jupiter-reading-'+key)||value}catch{}apply(key,value===(key==='size'?'large':'high')?value:'normal')}size.addEventListener('click',()=>apply('size',size.getAttribute('aria-pressed')==='true'?'normal':'large'));contrast.addEventListener('click',()=>apply('contrast',contrast.getAttribute('aria-pressed')==='true'?'normal':'high'));const header=document.querySelector('.customer>header,main>header');if(header)header.after(tools);else document.body.prepend(tools)})();</script>'''

def decorate(document):
    if 'id=reading-styles' in document or '</html>' not in document:return document
    return document.replace('</html>',CSS+SCRIPT+'</html>',1)
